  "package.json": "{\n  \"name\": \"indesign-automation-framework\",\n  \"version\": \"1.0.0\",\n  \"description\": \"Production-grade, packagable InDesign UXP automation framework and AI toolkit.\",\n  \"type\": \"module\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Noremack/indesign-automation-framework.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/Noremack/indesign-automation-framework/issues\"\n  },\n  \"homepage\": \"https://github.com/Noremack/indesign-automation-framework#readme\",\n  \"main\": \"./dist/index.cjs\",\n  \"module\": \"./dist/index.js\",\n  \"types\": \"./dist/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"import\": \"./dist/index.js\",\n      \"require\": \"./dist/index.cjs\",\n      \"types\": \"./dist/index.d.ts\"\n    },\n    \"./mock\": {\n      \"import\": \"./tests/mocks/indesign-mock.ts\",\n      \"types\": \"./tests/mocks/indesign-mock.ts\"\n    }\n  },\n  \"files\": [\n    \"dist\",\n    \"src\",\n    \"tools\",\n    \"tests/mocks\",\n    \"AI_MANIFESTO.json\",\n    \"antigravity.rules.json\",\n    \"app.config.json\",\n    \"setup-framework.mjs\",\n    \"README.md\"\n  ],\n  \"bin\": {\n    \"indesign-scaffold\": \"./tools/scaffold.mjs\"\n  },\n  \"scripts\": {\n    \"type-check\": \"tsc --noEmit\",\n    \"test:unit\": \"vitest run\",\n    \"test:watch\": \"vitest\",\n    \"build:script\": \"rollup -c --environment TARGET:script\",\n    \"build:plugin\": \"rollup -c --environment TARGET:plugin\",\n    \"build:lib\": \"rollup -c --environment TARGET:lib\",\n    \"build\": \"rollup -c\",\n    \"validate\": \"npm run type-check && npm run test:unit && npm run build\",\n    \"scaffold\": \"node tools/scaffold.mjs\",\n    \"prompt:pack\": \"node tools/pack-prompt.mjs\",\n    \"context:extract\": \"node tools/extract-context.mjs\"\n  },\n  \"devDependencies\": {\n    \"@rollup/plugin-commonjs\": \"^25.0.0\",\n    \"@rollup/plugin-node-resolve\": \"^15.2.0\",\n    \"@rollup/plugin-typescript\": \"^11.1.0\",\n    \"@types/node\": \"^26.6.5\",\n    \"rollup\": \"^4.0.0\",\n    \"tslib\": \"^2.8.1\",\n    \"typescript\": \"^5.3.0\",\n    \"vitest\": \"^1.0.0\"\n  }\n}\n",
