  "rollup.config.js": "import resolve from \"@rollup/plugin-node-resolve\";\nimport commonjs from \"@rollup/plugin-commonjs\";\nimport typescript from \"@rollup/plugin-typescript\";\nimport fs from \"fs\";\n\nconst config = JSON.parse(\n  fs.readFileSync(new URL(\"./app.config.json\", import.meta.url), \"utf8\")\n);\n\nconst target = process.env.TARGET || \"all\";\n\nconst builds = [];\n\nif (target === \"all\" || target === \"script\") {\n  builds.push({\n    input: config.mainScript,\n    output: {\n      file: `dist/scripts/${config.name}.idjs`,\n      format: \"cjs\",\n      exports: \"auto\",\n      sourcemap: true\n    },\n    external: [\"indesign\", \"uxp\", \"fs\"],\n    plugins: [\n      resolve(),\n      commonjs(),\n      typescript({ tsconfig: \"./tsconfig.json\" })\n    ]\n  });\n}\n\nfunction uxpManifestPlugin() {\n  return {\n    name: \"uxp-manifest\",\n    generateBundle() {\n      const manifest = {\n        manifestVersion: 5,\n        id: config.id,\n        name: config.name,\n        version: config.version,\n        description: config.description,\n        main: \"index.js\",\n        host: [\n          {\n            app: \"ID\",\n            minVersion: \"18.0\"\n          }\n        ],\n        entrypoints: [\n          {\n            type: \"panel\",\n            id: \"mainPanel\",\n            name: `${config.name} Panel`,\n            main: \"index.js\"\n          }\n        ],\n        requiredPermissions: config.permissions || {}\n      };\n\n      this.emitFile({\n        type: \"asset\",\n        fileName: \"manifest.json\",\n        source: JSON.stringify(manifest, null, 2)\n      });\n    }\n  };\n}\n\nif (target === \"all\" || target === \"plugin\") {\n  builds.push({\n    input: config.mainPlugin,\n    output: {\n      file: `dist/plugins/${config.name}/index.js`,\n      format: \"cjs\",\n      exports: \"auto\",\n      sourcemap: true\n    },\n    external: [\"indesign\", \"uxp\", \"fs\"],\n    plugins: [\n      resolve(),\n      commonjs(),\n      typescript({ tsconfig: \"./tsconfig.json\" }),\n      uxpManifestPlugin()\n    ]\n  });\n}\n\nif (target === \"all\" || target === \"lib\") {\n  builds.push({\n    input: \"src/index.ts\",\n    output: [\n      {\n        file: \"dist/index.cjs\",\n        format: \"cjs\",\n        exports: \"named\",\n        sourcemap: true\n      },\n      {\n        file: \"dist/index.js\",\n        format: \"esm\",\n        sourcemap: true\n      }\n    ],\n    external: [\"indesign\", \"uxp\", \"fs\"],\n    plugins: [\n      resolve(),\n      commonjs(),\n      typescript({ tsconfig: \"./tsconfig.json\" })\n    ]\n  });\n}\n\nexport default builds;\n",
